import numpy as np

# Final output - fill the triangular region
output = np.zeros((16, 16), dtype=int)

# Fill 9s area (top-right corner): c >= r + 14
for r in range(16):
    for c in range(16):
        if c >= r + 14:
            output[r, c] = 9

# Fill 1s area (between diagonals): r + 2 <= c < r + 14
for r in range(16):
    for c in range(16):
        if r + 2 <= c < r + 14:
            output[r, c] = 1

